/**
 * The authoritative link types.
 *
 * Palantir keeps a link type in the ontology, not in the module that happens to talk to one
 * provider: a link is a statement about the business ("a parcel belongs to a request"), while a
 * data source only supplies the instances of it. This file is that single authority. Modules that
 * declare links today are being migrated onto it; until they are, the registry is compared against
 * the compiled document so any drift fails loudly instead of silently forking the graph.
 *
 * Cardinality is copied from the declaration that is in service, which is a default rather than a
 * reviewed decision for most entries: required=false on the far side means "nobody asserted that an
 * orphan is illegal", not "orphans are fine".
 */
export type LinkTypeDeclaration = {
  apiName: string;
  from: string; fromName: string; fromMany: boolean; fromRequired: boolean;
  to: string; toName: string; toMany: boolean; toRequired: boolean;
  /** Role facets a declaration carries. Kept here so the graph can be synthesised from this table
   * alone once the provider modules stop declaring links. */
  roles: readonly string[] | null;
  description: string | null;
  /** Anything else a declaration carried (link attributes). Stored verbatim so the graph can be
   * synthesised from this table without changing a digest. */
  extras: Record<string, unknown> | null;
};

